  function S() {
    return global.S || (global.S = {});
  }

  function clamp(n, a, b) {
    return Math.max(a, Math.min(b, Number(n) || 0));
  }

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function industryKey(ctx) {
    ctx = ctx || {};
    var raw = String(ctx.industryKey || ctx.industry || ctx.industryLabel || ctx.seed ||
      (ctx.business && ctx.business.industry) || '').toLowerCase();
    if (/candle|soap|jewelry|handmade|merch|retail|product/.test(raw)) return 'maker';
    if (/photo|wedding/.test(raw)) return 'photography';
    if (/clean|maid|airbnb|turnover/.test(raw)) return 'cleaning';
    if (/hvac|heating|furnace|air\s*condition/.test(raw)) return 'hvac';
    if (/pressure|power\s*wash|soft\s*wash/.test(raw)) return 'pressure_washing';
    if (/lawn|landscap|mow/.test(raw)) return 'lawn';
    if (/spa|massage|salon/.test(raw)) return 'spa';
    return 'local_service';
  }

  function modelOf(ctx) {
    var key = industryKey(ctx);
    if (key === 'maker') return 'commerce';
    if (key === 'photography') return 'creative_services';
    return 'local_service';
  }

  function pickVoice(ctx, direction) {
    var key = industryKey(ctx);
    var d = String(direction || '').toLowerCase();
    var intent = (ctx.business && ctx.business.buyerIntent) || ctx.buyerIntent || '';
    var learned = null;
    try {
      if (global.HublyTaste && global.HublyTaste.preferredTraits) {
        var traits = global.HublyTaste.preferredTraits();
        if (traits.indexOf('storytelling') >= 0) learned = 'creative_studio';
        else if (traits.indexOf('bold') >= 0) learned = key === 'maker' ? 'boutique' : 'modern_expert';
        else if (traits.indexOf('minimal') >= 0 || traits.indexOf('simple') >= 0) learned = 'modern_expert';
      }
    } catch (e) {}

    if (learned) return VOICES[learned];
    if (key === 'maker') return intent === 'gift' ? VOICES.boutique : VOICES.craftsman;
    if (key === 'photography') return VOICES.creative_studio;
    if (key === 'cleaning' || key === 'pressure_washing') return d === 'bold' ? VOICES.modern_expert : VOICES.trusted_neighbor;
    if (key === 'hvac') return VOICES.modern_expert;
    if (key === 'lawn' || key === 'spa') return d === 'bold' ? VOICES.adventure : VOICES.local_family;
    return VOICES.trusted_neighbor;
  }

  /* ── 1. Business Story ── */

